INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(40500, 0, 405, 0, 0, 0, 'Desolace', 'Desolace is a grey and broken land southwest of the Stonetalon Mountains, a waste of bare rock, bleached bones and brackish yellow pools beneath a stormy sky. Only the western shore, where the Veiled Sea breaks on the Sar''theris Strand, keeps any green. This is the ancestral home of the centaur, whose holy ground of Maraudon lies hidden deep in the Valley of Spears. Their clans, the Kolkar, Gelkis, Magram and Maraudine, now fight one another across the plains, and outsiders dread the day they might unite. They are not the only danger. The night elves who once lived here are long gone, the Burning Blade holds Thunder Axe Fortress, demons gather at Mannoroc Coven, Hatefury satyrs haunt Sargeron and naga prowl the coast. The Alliance keeps watch from Nijel''s Point in the northern mountains, while the Horde holds Ghost Walker Post above the Kodo Graveyard and the troll fishing village of Shadowprey.', 'warcraft.wiki.gg/wiki/Desolace (grey rocky wasteland littered with bones, polluted yellow pools, stormy skies, lush western coast); quests 7064, 7065 descriptions (Zaetar, first son of Cenarius, and Theradras; centaur killed Zaetar); quest 1365 description (many clans fighting each other; dangerous if united); quest 1382 description; quest 1466 completion text (centaur owned the land after the night elves left); quest 1453 description (Nijel''s Point in the northern mountains); quest 1432 description (Ghost Walker Post north of the Kodo Graveyard); npc_text 6334, 6335 (Marandis and Selendra keep the details of their mission from the unproven)'),
(40501, 1, 405, 1, 0, 0, 'Nijel''s Point', 'Hidden in the mountains of northern Desolace, just east of the way in from Stonetalon, Nijel''s Point is a small Alliance camp, easily missed. No one there seems to know who Nijel was. Soldiers of Stormwind guard it under Captain Pentigast, who studies how to break the warring centaur clans, while Corporal Melkins pays for every centaur ear brought in. Night elves keep the inn and the hippogryph roost, and Vahlarriel Demonslayer has come from Darnassus to find two missing nobles. Kreldig Ungor of Reclaimers Inc. hunts down lost property for paying clients, Brother Anton preaches the cause of the Scarlet Crusade, and the keeper Marandis and his sisters of the Cenarion Circle have business with Maraudon.', 'quest 1453 description (cozy camp hidden in the mountains of northern Desolace, east from Stonetalon, easy to miss); quest 1456 completion text (No offense to whoever Nijel is); warcraft.wiki.gg/wiki/Nijel''s_Point (nobody knows who Nijel was); quests 1382, 1385 (Pentigast), 1387 (Melkins, centaur ears); quest 1437 (Vahlarriel, House Malem); quest 6141 (Brother Anton); npc_text 6334 (Marandis, mission of great importance to the Cenarion Circle); quest 7065; zone_areas area 608: Nijel''s Point Guard (template 11, Stormwind), Innkeeper Lyshaerya and Baritanas Skyriver (template 80, Darnassus), Marandis'' Sister; warcraft.wiki.gg/wiki/Kreldig_Ungor (quests present in Classic, removed 4.0.3a)'),
(40502, 1, 405, 2, 0, 0, 'Sargeron', 'In the northeastern corner of Desolace stand the ruins of a night elf city that has lain broken since the War of the Ancients, its true name forgotten. The Hatefury satyrs who infest it call it Sargeron, after their dark master Sargeras. Rogues, tricksters, betrayers, felsworn, hellcallers and shadowstalkers prowl the fallen streets as allies of the Burning Blade. Maurin Bonesplitter of Ghost Walker Post has a use for a shadowstalker''s scalp in his spellwork. Kreldig Ungor of Nijel''s Point doubts the tale that the satyr are tied to the night elves, blaming it on the one elf who brought them into the war a few years back.', 'warcraft.wiki.gg/wiki/Sargeron (night elf city in ruins since the War of the Ancients, name lost, satyrs renamed it after Sargeras); quest 1458 completion text (story says satyr are tied to night elves; one elf brought them into the war); quest 1481 description (shadowstalkers in the ancient ruins of the northeast); zone_areas area 603: Hatefury Rogue, Trickster, Felsworn, Betrayer, Hellcaller, Shadowstalker; quest 1481 description (Hatefury shadowstalker scalp to break wards against scrying)'),
(40503, 1, 405, 3, 0, 0, 'Thunder Axe Fortress', 'Thunder Axe Fortress rises in northern Desolace, just south of the ruins of Tethris Aran, and belongs to the Burning Blade, orcs who have given their loyalty to demons. From its stronghold, barracks and watchtowers the cult''s augurs, adepts, reavers, felsworn and shadowmages practice their dark craft. Within lies a red crystal sealing the Demon Box, which holds the Hand of Iruxos the cult uses to open portals at Mannoroc Coven, and atop one watchtower a Burning Blade seer studies the Sceptre of Light, taken from the naga. Not everyone within the walls belongs to the cult. Among the fires of the stronghold stands a night elf woman whom the orcs around her leave be.', 'warcraft.wiki.gg/wiki/Thunder_Axe_Fortress (stronghold, barracks, cave, watch towers); warcraft.wiki.gg/wiki/Tethris_Aran (ruins just north of the fortress); quest 1465 reward text (fortress infested with the Burning Blade, orcs dedicated to demon causes); quest 5381 description (Demon Box, red crystal in Thunder Axe Fortress, Hand opens portals at Mannoroc Coven); quest 5741 description (seer studies the sceptre atop a Thunder Axe watchtower; acquired from the naga); quest 1438 reward text (captured and brought here; sacrifice to demon masters); zone_areas area 599: Burning Blade Augur, Felsworn, Adept, Reaver, Shadowmage, Seer 13019, Tyranis 5643, Dalinda 5644, Hand of Iruxos Crystal 176581; posarea.py: Tethris Aran (2404) lies directly north of the fortress (599); DB: Dalinda 5644 template 10 (friendly to the Alliance, not hostile to the Horde), no cage or chains near her spawn; display 3791 night elf female'),
(40504, 1, 405, 4, 0, 0, 'Ethel Rethor', 'On the northwestern coast the ruins of Ethel Rethor lie mostly beneath the waves, a drowned night elf city whose only standing remnant is a lone tower reached by a small bridge. From it the Argent Dawn mage Azore Aldamort watches both the Slitherblade naga who haunt the shallows and the Burning Blade to the east. Nearby lies the chest of the Stormwind mage Karnitol, who abandoned it when sea giants fell upon his ship offshore and saved himself and his servants by magic, leaving it behind for whoever might come looking.', 'warcraft.wiki.gg/wiki/Ethel_Rethor (night elven ruin, mostly underwater, lone tower with small bridge; Argent Dawn representative); quests 5741, 6027 (Azore at the tower in Ethel Rethor; Thunder Axe to the east); quest 1454 description and reward text, 1455 description (Karnitol''s chest, sea giants, teleport, no water damage, traps triggered, scratches); zone_areas area 2405: Azore Aldamort 11863, Karnitol''s Chest 35251, Slitherblade naga'),
(40505, 1, 405, 5, 0, 0, 'Ranazjar Isle', 'On Ranazjar Isle, a small rocky island off the northwestern coast, Slitherblade sea witches, tidehunters, myrmidons and oracles gather about a great serpent statue. Close by, sunken night elf ruins on the sea floor serve the Slitherblade as a home. The Argent Dawn knows that a gem set in the statue''s hand will call forth the protector of the Book of the Ancients, which holds secrets the naga have kept for centuries. Drulzegar Skraghook''s fishing crew was slaughtered by naga near the isle, and when Rackmore''s ship was attacked by sea creatures on its way to Feathermoon Stronghold, he hid his treasure here in a chest that needs two keys, one silver and one gold.', 'warcraft.wiki.gg/wiki/Ranazjar_Isle (small rocky island off the northwest coast; serpent statue); quest 6027 description (Gem of the Serpent on the statue''s hand summons the book''s protector); smart_scripts 177673 (Serpent Statue summons Lord Kragaru 12369); quest 1456 description (night elf ruins at the bottom of the ocean near Ranazjar, Slitherblade home); quest 6143 description (crew killed by naga near Ranazjar Isle); quest 6161 description (Rackmore, Feathermoon, silver and gold keys); zone_areas area 2406: Slitherblade Sea Witch, Razortail, Myrmidon, Tidehunter, Oracle; Serpent Statue 177673; Rackmore''s Chest 177786'),
(40506, 1, 405, 6, 0, 0, 'Sar''theris Strand', 'The Sar''theris Strand runs along the western coast, the one stretch of Desolace that still knows sun and grass. Slitherblade naga come ashore from their reefs, drysnap crawlers scuttle in the surf, and Deepstrider giants wade the shallows, the kind of sea giants that drove a Stormwind mage from his ship off the northern shore. A wrecked ship lies off the coast north of Shadowprey Village, where soft-shelled clams prized by troll fishermen as bait litter the sea bed, and waterlogged footlockers turn up among the rocks. Near Shadowprey, the dryad Selendra and her sisters have come down from Stonetalon on a mission they cannot finish alone, and seek mortals strong enough to help.', 'warcraft.wiki.gg/wiki/Sar''theris_Strand (coast of Desolace, sea giants, naga, makrura; sunny and grassy unlike the rest); quest 1454 description (sea giants attacked Karnitol''s ship off the northwest coast); quest 6142 description (wrecked ship up north, soft-shelled clams, bait); npc_text 6335 (Selendra and her sisters came down from Stonetalon, not powerful enough alone); zone_areas area 598: Slitherblade naga, Drysnap Crawler/Pincer, Deepstrider Giant/Searcher, Giant Softshell Clam, Waterlogged Footlocker, Selendra 13699, Marandis'' Sister; zone_areas area 2324 (The Veiled Sea): Drysnap crawlers, shellfish traps'),
(40507, 1, 405, 7, 0, 0, 'Kormek''s Hut', 'Kormek''s Hut is a lonely shack on the barren flats of north-central Desolace, southeast of Thunder Axe Fortress, and of Kormek himself there is no sign. The goblin Bibbly F''utzbuckle has taken over its pen, sure that he is sitting on a goldmine. Kodo bones from the graveyard to the south, he claims, go into furniture, musical instruments and even blasting powder, and a caravan collects them to sell at Shadowprey Village. That caravan, the Gizelton brothers'' kodo train, halts on the road outside. Inside waits a stranger guest, Willow of the Twilight''s Hammer, who pays for crystal carvings from the caverns of Maraudon, relics of the old gods whose powers, Willow says, have been too long at rest.', 'warcraft.wiki.gg/wiki/Kormek''s_Hut (namesake unknown; Willow inside, Bibbly in the pen; barren flats before Cataclysm); quest 5501 description (goldmine, furniture, instruments, blasting powder; caravan sells bones at Shadowprey; graveyard south); quest 7028 description (Willow: Theradric crystal carvings, relics of the old gods, powers too long at rest); creature_text 11625, 11626 (caravan stops east of Kormek''s Hut; heads north to Kormek''s Hut); warcraft.wiki.gg/wiki/Gizelton_Caravan (northern stop SE of Thunder Axe outside Kormek''s Hut); zone_areas area 2407: Willow 13656, Bibbly F''utzbuckle 11438; quest 5561 description (the only caravan brave enough to travel these parts); creature_template_model 13656 display 13909 (female)'),
(40508, 1, 405, 8, 0, 0, 'Kolkar Village', 'The Kolkar hold the eastern reaches of Desolace from a village northeast of Ghost Walker Post, beneath the mountains. Desolace is their homeland, and from it their warbands have spread into the Barrens. The Horde holds that as long as the clan stays strong here it will always be a threat. Battle lords, destroyers, maulers, windchasers and scouts crowd the camp under Khan Dez''hepah. The rival clans scorn them: the Gelkis say the Kolkar would not know true magic if it bit them, and the Magram laugh as they kill them. Travelers fear them all the same. When the Gizelton caravan hears the Kolkar war drums, it stops dead on the road and waits for a bodyguard.', 'quest 1362 description (Kolkar live in Desolace, have spread into the Barrens, always a threat while strong here); barrens.json 1738 (quest 4021: Desolace their homeland); quest 1365 description (Kolkar Village northeast of Ghost Walker Post); quest 1384 description (Gelkis scorn of Kolkar magic); quest 1386 description (Magram laugh and kill them); quest 5821 description (war drums stop the caravan); zone_areas area 609: Kolkar Battle Lord, Windchaser, Mauler, Scout, Centaur, Destroyer, Khan Dez''hepah 5600; warcraft.wiki.gg/wiki/Kolkar_clan (village in eastern Desolace near the mountains)'),
(40509, 1, 405, 9, 0, 0, 'Scrabblescrew''s Camp', 'Smeed Scrabblescrew''s camp sits beside the road through central Desolace, a goblin''s stake in the one caravan bold enough to brave these lands. Smeed claims to have learned how to rejuvenate and control aged and dying kodo with a device of his own, the kodo kombobulator, which jolts the beasts into tame pack animals. He supplies them to Cork and Rigger Gizelton, whose caravan pays his bills, and he pays the bodyguards who see it safely through, though he grumbles at every coin. Smeed fancies himself a far better businessman than Bibbly F''utzbuckle of Kormek''s Hut, and can hardly wait to see the look on his rival''s green face when word of his success gets around.', 'quest 5561 description and reward text (kombobulator, partnership with Cork and Rigger, Bibbly''s green face); quest 5821 completion and reward text (they pay the bills; doubts about paying guards); quest 5943 reward text; zone_areas area 2617: Smeed Scrabblescrew 11596, Gizelton Caravan Kodo 11564'),
(40510, 1, 405, 10, 0, 0, 'Ghost Walker Post', 'Ghost Walker Post is a tauren outpost in central Desolace, north of the great Kodo Graveyard, reached by the road south from the Charred Vale. From here the Horde deals with the centaur clans and the Burning Blade. The tauren Gurda Wildmane seeks an alliance with one of the clans, while Felgur Twocuts gathers intelligence on them. Orgrimmar sent its own envoys, the orc swordsman Takata Steelblade and the Forsaken warlock Maurin Bonesplitter, to root out the demons, at the word of Keldran. Ghost Walker braves keep watch, Nataka Longhorn longs for fried fish from Shadowprey, and Narv Hidecrafter swears the strongest hides come from kodo that have laid themselves to rest in this wasteland.', 'quest 1432 description (Ghost Walker Post north of the Kodo Graveyard; south of the Charred Vale); quest 5361 description (road south to Ghost Walker Post); warcraft.wiki.gg/wiki/Ghost_Walker_Post (tauren outpost, Gurda Wildmane leads); quests 1367, 1368 (Gurda: ally with one clan); quest 1362 description (Felgur sent to gather intelligence on the centaur); quests 1433, 1434 (Takata, Maurin sent by Keldran); quest 5386 description (Nataka, Bloodbelly fish from Shadowprey); npc_text 5335 (Narv Hidecrafter on kodo hides); zone_areas area 597: Ghost Walker Brave, Takata 5641, Felgur 5395, Gurda 5412, Maurin 4498, Nataka 11259, Narv 8153; warcraft.wiki.gg/wiki/Gurda_Wildmane (tauren; shaman only in non-canon RPG)'),
(40511, 1, 405, 11, 0, 0, 'Kodo Graveyard', 'South of Ghost Walker Post spreads the Kodo Graveyard, a field of enormous skeletons where kodo come to lay themselves to rest. Aged, dying and ancient kodo wander slowly among the bones of their kin, and carrion horrors haunt the field. Many of the bones seem to have belonged to beasts far larger than any kodo alive today, and grave moss grows thick in their shadow. Where death gathers, so do goblins. Bibbly F''utzbuckle of Kormek''s Hut pays for every bone carried out of here, and Hornizz Brimbuzzle keeps a camp at the graveyard''s edge, forever waiting on his restless sister Melizza and the next deal, even one made of ghosts.', 'warcraft.wiki.gg/wiki/Kodo_Graveyard (bones, sick and dying kodo, scavengers; bones of larger kodo; grave moss); quest 1432 description (great Kodo Graveyard south of Ghost Walker Post); quest 5501 (Kodo Bones from the Kodo Graveyard); quest 6132 description (Hornizz at our camp next to the kodo graveyard); quest 6132 completion text and creature_text 6019 (Melizza always on the go); quest 6134 (selling ghost-o-plasm to the Magram); zone_areas area 596: Carrion Horror, Dying/Aged/Ancient Kodo, Kodo Bones, Grave Moss, Hornizz Brimbuzzle 6019'),
(40512, 1, 405, 12, 0, 0, 'Mannoroc Coven', 'Named for the pit lord Mannoroth, Mannoroc Coven lies south of Ghost Walker Post among old night elf ruins, a land already dead that the demons have blasted further with fel magic. Burning Blade summoners opened portals here, and through them the Legion came: lesser infernals, doomwarders, felhounds that hunt mages, and succubi called nether maidens, sisters and sorceresses. Their master is the demon lord Azrethoc, and the orc warlock Jugkar Grim''rod serves at his side. Even the Gizelton caravan''s kodo shy at the coven. At its southern edge an exiled centaur, the Pariah, nurses his dream of a single great tribe.', 'warcraft.wiki.gg/wiki/Mannoroc_Coven (named after Mannoroth; night elven ruins; dead land blasted with fel magic; Burning Blade summoned demons through portals); quest 1488 description (directly south of Ghost Walker Post; demon lord and his warlock servant); quest 1480 reward text (contract signed Lord Azrethoc); quest 1466 description (felhound brains from mana eaters, mage hunters, ley hunters; nether maiden, sister, sorceress; doomwarder); quest 5943 description (demons normally ignore the caravan; kodos spooked); quest 5381 (portals at Mannoroc Coven); zone_areas area 602: Lesser Infernal, Nether Maiden/Sorceress/Sister, Mage Hunter, Ley Hunter, Doomwarder, Burning Blade Summoner, Lord Azrethoc 5760, Jugkar Grim''rod 5771, Centaur Pariah 13717, Demon Portals; DB positions: Centaur Pariah (-2146,1966) south of every coven demon spawn; Azrethoc (-1819,1673) south of Takata (-1178,1870); warcraft.wiki.gg/wiki/Jugkar_Grim''rod (orc warlock)'),
(40513, 1, 405, 13, 0, 0, 'Shadowbreak Ravine', 'Hidden in the mountains southeast of Magram Village, Shadowbreak Ravine is a secret enclave of the Burning Blade, far from the eyes of travelers on the road. Summoners and invokers of the cult practice their arts here, kin to those who call demons into Mannoroc Coven, and ley hunters, felhounds that feed on magic, prowl among them. The cultists keep something else in the ravine as well: captured stallions, kept beside dark steeds that bear the cult''s name, the Burning Blade nightmares. What the cultists mean to do with them they do not say.', 'warcraft.wiki.gg/wiki/Shadowbreak_Ravine (hidden valley in the mountains southeast of the Magram village; Burning Blade hideout); zone_areas area 2198: Burning Blade Summoner 4668, Burning Blade Invoker 4705, Ley Hunter 4685, Burning Blade Nightmare 13836, Captured Stallion 13837; quest 1466 (ley hunters are felhounds); DB positions: ravine ~(-1938,650) southeast of Warug (-1591,863)'),
(40514, 1, 405, 14, 0, 0, 'Magram Village', 'The Magram centaur hold the southeast of Desolace, their camps spread out at the foot of the eastern mountains. They are a clan that respects only strength. Wranglers, stormers, marauders, maulers and windchasers run with their bonepaws, and sacks of dried meat are stored so the clan can fight longer between hunts. Khan Jehn rules them, and the Gelkis would like nothing better than his head. On the outskirts, under the eyes of his bodyguards, waits Warug, the clan''s spokesman, who will hear any outsider strong enough to slay the Gelkis. To the Magram, the Gelkis faith in their mother Theradras is nothing but weakness, and they mean to prove it.', 'warcraft.wiki.gg/wiki/Magram_clan (southeastern Desolace, yurts among acrid pools; respect only strength); quest 1367 description (Warug on the outskirts of the Magram Village in southeast Desolace); quest 1370 description (Magram store extra meat); quest 1374 reward text (Khan Jehn strong but stupid, thought his own strength great); quest 1369 description (Theradras protects no one; Magram strongest); zone_areas area 604: Magram Wrangler, Windchaser, Stormer, Marauder, Mauler, Bonepaw, Sack of Meat, Warug''s Bodyguard, Warug 5398, Khan Jehn 5601; warcraft.wiki.gg/wiki/Magram_clan (Warug at the base of the mountains on the eastern borders); quest 1374 description (Uthek wants the head of Khan Jehn)'),
(40515, 1, 405, 15, 0, 0, 'Valley of Bones', 'At the southern edge of Desolace lies the Valley of Bones, a crag where the vast skeletons of two Dead Goliaths have collapsed against the cliffs, their origin unknown. Undead ravagers stalk its floor, outcast necromancers move among them, and the valley is haunted by the ghosts of the Magram. It draws outsiders all the same. Brother Anton of the Scarlet Crusade sends would-be recruits here to destroy the ravagers as proof of their resolve, and the goblin Hornizz Brimbuzzle hands out crates of ghost magnets to lure the spirits between the two great skeletons, sure that the Magram will pay a fortune for captured ghost-o-plasm, if only he can convince them what it is.', 'warcraft.wiki.gg/wiki/Valley_of_Bones (crag on the southern edge; two Dead Goliaths of unknown origin; necromancers; Magram ghosts); quest 261 description (undead ravagers in the Valley of Bones); quest 6134 description and reward text (haunted by Magram ghosts; ghost magnets between the Dead Goliaths); zone_areas area 2657: Undead Ravager 11561, Outcast Necromancer 11559'),
(40516, 1, 405, 16, 0, 0, 'Gelkis Village', 'The Gelkis centaur dwell in the far southwest of Desolace, their village ringing a ravine crossed by bridges beside the main road south. Theirs is the clan of the earth. Their shamans call on Theradras, whom they hold to be the mother of the centaur, and trust that she protects them. In the cave of Bolgan''s Hole, where Khan Shaka keeps his seat, they hoard the blue crystals called tears of Theradras. The shaman Uthek the Wise waits in a tent on the outskirts for strangers willing to spill Magram blood. The Gelkis and the Magram are brother clans and mortal enemies, set apart by faith in the earth against faith in strength.', 'warcraft.wiki.gg/wiki/Gelkis_clan (village ringing a ravine with bridges, on the main road, khan in a cave; respect nature and Theradras); warcraft.wiki.gg/wiki/Bolgan''s_Hole (cave in Gelkis Village; khan''s home; tears of Theradras); quest 1369 description (Gelkis think Theradras protects them; crystals hoarded in the cave); quest 1368 description (Uthek, Gelkis shaman, outskirts, southwest); zone_areas area 606: Gelkis Windchaser, Stamper, Earthcaller, Rumbler, Tear of Theradras, Uthek 5397; Khan Shaka 5602 and more tears inside the cave (outdoor grid reads 405); WMOAreaTable.dbc: WMO 2933 rows map to AreaTable 600 (Bolgan''s Hole), so it is an indoor area; warcraft.wiki.gg/wiki/Bolgan''s_Hole (blue crystals called tears of Theradras); warcraft.wiki.gg/wiki/Gelkis_clan (Magram a brother tribe and mortal enemies; Uthek in a small tent)'),
(40517, 1, 405, 17, 0, 0, 'Valley of Spears', 'The Valley of Spears in western Desolace belongs to the Maraudine, the clan that guards Maraudon, holy ground where only spirits and the most sacred priests may tread. Maraudine scouts, stormers and priests roam its canyons, and ghostly raiders ride among them. A war horn stands atop a high bluff, and its call brings the clan''s warriors and at last Khan Hratha himself. In the caves at the valley''s end the dryad Cavindra begs for help for her cursed brother and sisters, and the Nameless Prophet, one of the oldest of all the tribes, communes with the spirits of the ancestors. The goblin Melizza Brimbuzzle came here to trade and ended up in a cage.', 'warcraft.wiki.gg/wiki/Valley_of_Spears and Maraudine_clan (Maraudine home, entrance to Maraudon); page_text 2591, 2592 (holy temple of Maraudon, only spirits and sacred priests; the Nameless Prophet, highest in spiritual matters, one of the oldest, communicates with the spirits); quests 1380, 1381 (war horn on a high bluff, Khan Hratha); npc_text 6574 (Cavindra: brother and sisters trapped inside); quest 6132 description (Melizza came to do business with the Maraudines); zone_areas area 607: Maraudine Scout/Wrangler/Windchaser/Mauler/Stormer/Marauder/Priest, Ghostly Raider/Marauder, Ambereye Basilisk/Reaver, Shadowshard/Ambershard elementals, Cavindra 13697, Nameless Prophet 13718, Spirits of Kolk/Gelk/Magra, Melizza 12277 and her cage, Mouthpiece Mount 138497; warcraft.wiki.gg/wiki/Cavindra (dryad, sister of Celebras)'),
(40518, 1, 405, 18, 0, 0, 'Shadowprey Village', 'Shadowprey Village is a Darkspear troll fishing village on the western coast of Desolace, its docks reaching into the sea, and its catch is wanted inland at Ghost Walker Post. Tauren keep the inn and the wind riders. Fishermen of every temper work the docks: Jinar''Zillen pays others to empty his shellfish traps, Mai''Lahii would rather fish than sell tackle, and Drulzegar Skraghook lives only for revenge on the naga who killed his crew. Taiga Wisemane fights the demons of Mannoroc Coven, Vark Battlescar works to heal the corruption of Maraudon, and the tauren Roon Wildmane remembers the days he hunted with the dwarf Hemet Nesingwary.', 'warcraft.wiki.gg/wiki/Shadowprey_Village (troll fishing village; tauren run inn, stable, flight master; fish supplies Ghost Walker Post); quest 5386 description (trolls are the best fishers; fish wanted at Ghost Walker Post); quest 5421 completion text (shellfish traps below the docks); npc_text 4959 (Mai''Lahii); quest 6143 (Drulzegar''s crew); quests 5381, 5581 (Taiga); quest 7029 (Vark, Vyletongue corruption); quest 5763 description (Roon and Hemet hunted together); quest 6567 description (Rokaro holds Rexxar''s information); zone_areas area 2408: Shadowprey Guardian, Darkspear vendors (template 126), Innkeeper Sikewa, Aboda, Thalon (template 104); mod-individual-progression zone_desolace.sql (10182 renamed Rexxar and respawned as a wanderer on the Desolace roads in every state)'),
(40519, 2, 405, 1, 0, 0, 'Warug', 'Warug speaks for the Magram clan, on the edge of Magram Village, his bodyguards close at hand. He respects strength and nothing else, and will not speak with anyone who has not slain many Gelkis. For those who have, he has work: smash the tears of Theradras the Gelkis hoard, bring him the head of Khan Shaka so he can stare at it and laugh, and break the Maraudine. He laughs when he kills, so the enemy can see he is weak. Yet Warug has a childish streak. Long ago he killed a gnome who came with a cart of strange moving things, and he still wants a new wooden target dummy to replace the one he broke.', 'quest 1367 completion and reward text; quest 1369; quest 1375 description and reward text; quest 1381; quest 1386 reward text (better to laugh when you kill); quest 1371 description (the gnome, the waving wooden human); warcraft.wiki.gg/wiki/Warug; DB: template 35 (friendly to both), Warug''s Bodyguard 6068'),
(40520, 2, 405, 2, 0, 0, 'Uthek the Wise', 'Uthek the Wise is a shaman of the Gelkis who keeps a tent on the outskirts of their village and listens to what the earth tells her. To strangers whose hands are wet with Magram blood she gives tasks and counsel: the Magram hoard meat to fight longer, the Kolkar know nothing of true magic, and the earth has whispered to her of a red crystal called draenethyst, new to this world, from a place where mountains fly and demons rule. For a shard of it she would send an ally as far as the Swamp of Sorrows. Earth magic, Uthek says, is stronger than any khan''s might, and one day the Gelkis will rule.', 'quest 1368 completion and reward text; quest 1382 (through her); quest 1370 description; quest 1384 description; quest 1373 description (draenethyst, mountains fly, demons rule; Ongeku in the Swamp of Sorrows); quest 1374 reward text (earth magic stronger; Gelkis will one day rule); warcraft.wiki.gg/wiki/Uthek_the_Wise (female); creature_template_model 5397 display 4875 (female)'),
(40521, 2, 405, 3, 1, 0, 'Captain Pentigast', 'Captain Pentigast commands the Stormwind soldiers who guard Nijel''s Point. He sees Desolace as a land at war, and fears that whichever centaur clan wins will spill out and threaten the Alliance''s strongholds. His answer is cold reckoning. The clans fight among themselves, and if they ever joined into one force they would be unstoppable, so the Alliance must press its advantage: side with the Gelkis or the Magram, earn their favor by killing their rivals, and learn from them how to beat all the centaurs. His corporal, Melkins, holds to a simpler policy, paying for centaur ears in the belief that each one brings the war a step closer to its end.', 'quest 1382 description; quest 1385 description; quest 1387 description and reward text (Corporal Melkins); warcraft.wiki.gg/wiki/Captain_Pentigast (human, Stormwind)'),
(40522, 2, 405, 4, 2, 0, 'Takata Steelblade', 'Takata Steelblade is an orc swordsman of Orgrimmar who stands watch at Ghost Walker Post against the demons of Desolace, beside the Forsaken warlock Maurin Bonesplitter. He is a soldier first, bound to his post by duty to the Warchief and by the honor of his clan. The fight wears on him. The demons only seem to multiply, his hope of returning to the Warchief dwindles, and at times he wishes the centaur were his only foes.', 'quest 1484 description (Takata may question Maurin; it would insult his honor not to be told); quest 1484 reward text (apparition more powerful than his warlock companion; would disgrace his clan to leave his duties for his own honor); quest 1488 description, completion and reward text (gather a party; demons multiply; wishes it were only centaur; a place to call home again); warcraft.wiki.gg/wiki/Takata_Steelblade (orc); DB: Takata 5641 spawned in area 597, template 29 (Orgrimmar)'),
(40523, 2, 405, 5, 2, 0, 'Maurin Bonesplitter', 'Maurin Bonesplitter is a Forsaken warlock at Ghost Walker Post who knows the ways of the Burning Blade and holds them in contempt: their magic is feeble, he says, and what power they have is borrowed from the masters they serve, not born of any understanding of true power. He works with care, for in his craft a wrong reagent could kill the one who uses it, and fate, he admits, has dealt him pain enough. He keeps company with the swordsman Takata Steelblade, who stands watch beside him against the demons of Desolace.', 'quest 1480 completion and reward text (their only power comes from those they serve; runes remotely similar to Eredun; contract); quest 1481 completion text (wrong reagents could cause our deaths; fate has dealt me enough pain); quest 1482 completion text (favor with the Warchief; further our own ends); quest 1484 description (better if Takata thinks it his own idea); warcraft.wiki.gg/wiki/Maurin_Bonesplitter (Forsaken); DB: Maurin 4498 spawned in area 597, template 68 (Undercity)'),
(40524, 2, 405, 6, 0, 0, 'Tyranis Malem', 'Tyranis Malem is a night elf found within Thunder Axe Fortress, the stronghold of the Burning Blade. He walks free among the orc cultists rather than lying in their chains, and when strangers break into the fortress he takes up arms beside the cult and fights to the death against them. What brought an elf so far from the forests of his people, into the company of orcs who have given themselves to demons, is not something the fortress will tell.', 'quest 1437 description (House Malem, Darnassian merchant family); quest 1438 description and reward text (concern over Tyranis'' motives; craving for the arcane against his people''s wishes; warnings of demons); quest 1439 description and completion text (guards slaughtered; tried to impress them; might count himself among their kind); quest 1439 reward text (his death was necessary); warcraft.wiki.gg/wiki/Thunder_Axe_Fortress (Tyranis, traitor to his own people); DB: Tyranis Malem 5643 template 16, hostile, spawned in area 599; DB: display 3790 is NightElfMale (CreatureDisplayInfoExtra race 4)'),
(40525, 2, 405, 7, 0, 0, 'Azore Aldamort', 'Azore Aldamort is a human mage of the Argent Dawn who keeps the lone tower of Ethel Rethor on the northwestern coast, with two threats in view. The Burning Blade of Thunder Axe Fortress is rumored to have taken the Sceptre of Light from the naga, an artifact said in legend to sink whole cities beneath the sea, and a seer of the cult studies it from a watchtower. The Slitherblade naga, meanwhile, guard secrets kept for centuries in the Book of the Ancients, watched over by a protector on Ranazjar Isle. To trusted allies Azore entrusts the Gem of the Serpent, which calls that protector out.', 'quest 5741 description and reward text; quest 6027 description and reward text (high council); warcraft.wiki.gg/wiki/Azore_Aldamort (human mage, Argent Dawn); DB: template 794 (friendly to both); 5741, 6027 AllowableRaces 0'),
(40526, 2, 405, 8, 1, 0, 'Brother Anton', 'Brother Anton is an emissary of the Scarlet Crusade. Hearing rumors of an undead infestation in distant Desolace, he booked passage to Kalimdor at once to seek out and destroy it, and now preaches at Nijel''s Point. His creed is war with the Scourge, an evil that corrupts the people and infects the land. Those who would join must first prove themselves against the undead ravagers of the Valley of Bones. The worthy he sends back across the sea with a letter of commendation for Raleigh the Devout in Southshore, who will escort them to the Crusade''s Scarlet Monastery, for the true threat of the plague, he insists, lies in Lordaeron.', 'quest 6141 description (rumors of undead infestation; booked passage); quest 261 description and reward text; quest 1052 description (letter to Raleigh the Devout, Scarlet Monastery, true threat in Lordaeron)'),
(40527, 2, 405, 9, 0, 0, 'The Centaur Pariah', 'At the southern edge of Mannoroc Coven lives a centaur exiled as a heretic, known only as the Pariah. He needs no home, he says, to know he still has a place in this world. The tribes fight one another for scraps left by vultures and lands infested by the Legion, when their heritage is as noble as any night elf''s or orc''s. His dream is one great tribe, and exile has not shaken his belief in it. For his destiny to be complete he needs an outsider of no tribe, one willing to enter the holy halls of Maraudon, a tomb only the most devout of his people may enter.', 'npc_text 6353 (gossip: scraps left by vultures, lands infested by the Legion, heritage as noble as any night elf''s or orc''s); quest 7067 description and reward text (exiled as a heretic; one great tribe); page_text 2591-2596 (Nameless Prophet, Amulet of Spirits, five gems, five khans, Amulet of Union); warcraft.wiki.gg/wiki/Centaur_Pariah; DB: template 35; spawn reads as area 602'),
(40528, 3, 405, 1, 2, 0, 'The Kolkar of Desolace', 'From his bunkers in the Barrens, Regthar Deathgate recruits agents for a mission against the centaur of Desolace, a land torn by war, for as long as the Kolkar stay strong in their homeland they will threaten the plains. His volunteers go to Felgur Twocuts at Ghost Walker Post, who has been gathering intelligence on the clans and warns that the struggle will be long. Many clans wander the dry plains, fighting and dying against each other, and that is a mercy, for united they would be a fierce foe. The Horde must act before they unite, and Felgur means to start with the Kolkar leader, Khan Dez''hepah, in his village to the northeast. At the same post Gurda Wildmane has a subtler plan: ally with one clan and learn from it how to defeat them all.', 'quest 1361 description and reward text; quest 1362 description and reward text; quest 1365 description and reward text; quest 1366 description and reward text; quests 1367, 1368 descriptions (Gurda Wildmane)'),
(40529, 3, 405, 2, 0, 0, 'The War of the Clans', 'Captain Pentigast at Nijel''s Point and Gurda Wildmane at Ghost Walker Post reach the same conclusion: the way to beat the centaur is through their hatred of one another. United, the clans would be unstoppable; divided, they can be played against one another, and whoever wins the friendship of one may learn from it the way to beat them all. One who slays enough Magram may win a hearing with Uthek the Wise of the Gelkis, while one who slays Gelkis may stand before Warug of the Magram. Neither clan gives its trust freely. Each sets its new friends task after task written in the blood of its rivals, and Alliance champions are sent against the Kolkar as well.', 'quests 1382, 1385 (Alliance, Pentigast) and 1367, 1368 (Horde, Gurda) descriptions; quests 1370, 1373, 1374 (Gelkis tasks); quests 1369, 1371, 1375 (Magram tasks); quests 1384, 1386 (Alliance Kolkar tasks); quests 1380, 1381 descriptions and reward texts (war horn, Khan Hratha, key fragment, each clan will rule)'),
(40530, 3, 405, 3, 1, 0, 'Vahlarriel''s Search', 'House Malem, a Darnassian merchant family, sent Vahlarriel Demonslayer to Nijel''s Point when two of its children, Dalinda and Tyranis, went missing. Last word told of them passing through the Stonetalon Mountains a few weeks ago, bound for Desolace. Their father fears the worst. Vahlarriel is charged to do everything possible to find them, and hopes not to be in this grim land for long. The search begins on the road, with the siblings'' wagon, and anyone who finds it is asked to come to Nijel''s Point at once.', 'quest 1437 description and reward text; quest 1465 description and reward text (pendant, footprints south, smoke from a kept fire, Burning Blade fortress); quest 1438 description and reward text; quest 1439 description, completion and reward text; quest 1440 reward text (arrived under her own power; Tyranis'' embarrassment hers to endure); creature_text 5644 (escort lines)'),
(40531, 3, 405, 4, 2, 0, 'The Corrupter', 'Among the Burning Blade''s cultists some carry a strip of flayed demon skin, rotten-smelling and strangely supple for something that looks so dry and fragile. Red markings in some unknown language cover one side, and at the bottom sits a clear symbol that seems to be a signature of some kind. Such a thing belongs before Maurin Bonesplitter at Ghost Walker Post, a Forsaken warlock who knows the cult''s ways and scorns them. If anyone in Desolace can tell what the markings say, and whose mark is set beneath them, it is he.', 'quest 1480 description and reward text; item 20310 Flayed Demon Skin starts 1480; dropped by Burning Blade creatures; quests 1481, 1482 descriptions; creature_text 4498 (I call your true name, Azrethoc); quest 1484 description and reward text; quest 1488 description, completion and reward text'),
(40532, 3, 405, 5, 2, 0, 'The Hand of Iruxos', 'Taiga Wisemane of Shadowprey Village has learned that the Burning Blade possesses a Demon Box holding the Hand of Iruxos, the relic the cult uses to open demonic portals at Mannoroc Coven and let a tide of demons into the world. The box lies sealed within a red crystal at Thunder Axe Fortress, the cult''s stronghold in the north, and Taiga provides a demon pick to break it free. The tide must be stopped, and Taiga wants the box carried back to Shadowprey, pick and all, so that what lies inside can be turned to that end.', 'quest 5381 description and reward text; quest 5581 description and reward text; smart_scripts 176581 (Hand of Iruxos Crystal summons Demon Spirit 11876); smart_scripts 177243 (Demon Portal summons Demon Portal Guardian 11937)'),
(40533, 3, 405, 6, 1, 0, 'The Karnitol Shipwreck', 'Reclaimers Inc., the Ironforge firm that finds what people have lost for the right price, sent the dwarf Kreldig Ungor to Nijel''s Point with a list of jobs. The first is for Karnitol, a mage and noble of Stormwind, whose ship was attacked by sea giants off the northwest coast. He tried to bring a valuable chest ashore, then abandoned it and teleported himself and his servants to safety, and now he wants it found. The other is a shopping list for Leftwitch, a gnome mage of Kharanos, beginning with horns and claws from the Hatefury satyr. Roetten in Ironforge thinks it easy coin, though Kreldig is short-handed as it is.', 'quest 1453 description and reward text; quests 1454, 1455, 1456 descriptions and reward texts; quest 1457; quests 1458, 1459, 1466 descriptions; quest 1466 completion text (did not realize demons were in Desolace); quest 1467'),
(40534, 3, 405, 7, 0, 0, 'The Gizelton Caravan', 'The goblin brothers Cork and Rigger Gizelton run the only caravan brave enough to cross Desolace, a kodo train hauling their wares between a stop outside Kormek''s Hut in the north and another on the southern road east of Shadowprey Village. At each stop a selling machine opens for business, Cork''s Vendor-Tron 1000 and Rigger''s Super-Seller 680, and Cork, his brother says, is sure his own will sell more. The road between is perilous. Near the Kolkar village the centaur war drums make the brothers halt until someone will guard them past, and farther south, where the demons of Mannoroc Coven usually ignore them, something has spooked the kodo. Bodyguards collect their pay from the brothers'' partner Smeed Scrabblescrew, who supplies the kodo.', 'quest 5821 description and reward text; quest 5943 description and reward text (one gold piece a week); npc_text 4813, 4815 (Vendor-Tron 1000, Super-Seller 680); creature_text 11625, 11626 (stops near Kormek''s Hut and east of Shadowprey Village); quest 5561 (Smeed supplies the kodo); warcraft.wiki.gg/wiki/Gizelton_Caravan (route and stops)'),
(40535, 3, 405, 8, 0, 0, 'The Corruption of Maraudon', 'At the end of the Valley of Spears lies Maraudon, holy ground of the centaur and the root of their story. Keeper Marandis at Nijel''s Point and Selendra near Shadowprey have come down from Stonetalon with their sisters on a mission for the Cenarion Circle, to lay to rest a sorrow from ages past, and they seek allies strong enough to see it done. The caverns are fouled besides: the satyr Lord Vyletongue poisoned them and made Noxxion as a living symbol of his corruption. Talendria and Vark Battlescar seek to heal the vines he twisted, and Cavindra pleads for her brother Celebras, wandering cursed within, his scepter stolen in two pieces.', 'quests 7064, 7065 descriptions and completion texts (Zaetar, first son of Cenarius, brother of Remulos; Theradras kin to the Old Gods; remains; return to Stonetalon); quest 7044 description (Vyletongue, Noxxion, Celebras, scepter in two parts); quests 7029, 7041 descriptions (Vylestem vines); npc_text 6574 (Cavindra barely escaped); warcraft.wiki.gg/wiki/Zaetar, Maraudon (pre-Cataclysm); npc_text 6334, 6335 (Marandis and Selendra withhold the details from the unproven)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(40503, 1, 0, 255, 'She is Dalinda Malem, of a Darnassian merchant house, and no guest of the cult but its captive. The Burning Blade seized her and her brother Tyranis and carried them here, and she believes she is meant as a sacrifice to the cult''s demon masters.', 'quest 1438 reward text (captured and brought here by the Burning Blade; sacrifice to their demon masters); quest 1437 description (House Malem, Darnassian merchant family)'),
(40504, 1, 0, 255, 'Something reached Karnitol''s chest before any searcher did. It sits dry for all the sea around it, its lid prised open and the scorch of its spent wards still on the rim, and its sides are torn by deep furrows that neither man nor giant, sword nor dagger, would leave. Nothing remains inside.', 'quest 1454 reward text (no water damage; forced open; traps triggered, burn marks); quest 1455 description (scratches not made by dagger or sword, something other than a man or giant; empty); DB: 1455 starts from the chest 35251, right after 1454 ends there'),
(40505, 1, 0, 255, 'The protector the gem calls forth is Lord Kragaru. When the gem is set in the serpent''s hand, a beam of light springs up at the shrine and he appears beside the statue in a whirl of wind, and he fights hard for what he guards.', 'smart_scripts 177673 (Serpent Statue: naga beams, summons Lord Kragaru 12369); smart_scripts 12369 (Cyclone Visual Spawn on respawn); quest 6027 description (gem summons the book''s protector); gameobject_summon_groups 177673 (one Naga Beam 177705); smart_scripts 12369 (Cyclone Visual Spawn on spawn); 12369 has no creature spawn and is summoned only at the statue (with mod-individual-progression too, via the Naga Beam)'),
(40522, 1, 0, 255, 'When Maurin''s scrying called up the image of the demon lord Azrethoc, Takata watched, and judged that even as an apparition the creature held more power than his companion. He doubted the warlock was equal to it. Going himself would serve the Warchief better, yet to leave his duties for his own honor would disgrace his clan.', 'quest 1484 reward text (apparition more powerful than his warlock companion; would disgrace his clan to leave his duties); quest 1488 description (must be stopped; influence over the Burning Blade; gather a party; head south)'),
(40522, 2, 0, 255, 'Bound to his post, Takata trusted others to gather a party and strike south at the demon lord. When Azrethoc and his warlock servant fell, he hailed a mighty victory for all, and his outlook brightened: the demons would be slain, the Burning Blade would fail, and the Horde''s future in this land seemed far less bleak than he had feared.', 'quest 1488 reward text'),
(40523, 1, 0, 255, 'Maurin needed only a look at the flayed skin the cult carried. The writing was an old tongue, he judged, with a remote likeness to Eredun and drastic differences, and the thing itself a pact of some kind, sealed with a demon''s mark: the signature of Lord Azrethoc.', 'quest 1480 reward text (runes remotely similar to Eredun; contract; signature Lord Azrethoc)'),
(40523, 2, 0, 255, 'Maurin''s zeal is not only duty. Slaying Azrethoc would earn great favor with the Warchief, favor he means to spend on ends of his own. And when the demon lord''s image proved stronger than he had bargained for, he did not ask the proud Takata Steelblade outright, but had the swordsman told of it gently, judging it best that Takata believe the hunt his own plan.', 'quest 1482 completion text (favor with the Warchief; further our own ends); quest 1484 description (far more dangerous than anticipated; better if Takata thinks it his own idea); creature_text 4498 (the scrying)'),
(40524, 1, 0, 255, 'He was a son of the Darnassian merchant house of Malem, and he and his sister Dalinda came to Desolace though both were warned of its demons. Of late he had hungered for arcane power, a thing his people count a crime to pursue, and Darnassus already doubted him. Taken by the cult, he tried to win his captors with his learning, and in the end he stood with them. To his sister his death was terrible, but necessary.', 'quest 1437 description (House Malem, Darnassian merchant family); quest 1438 description and reward text (superiors'' concern over his motives; craving for the arcane; warned of demons); quest 1439 description, completion and reward text (tried to impress them; might count himself among their kind; his death was necessary)'),
(40525, 1, 0, 255, 'The sceptre was taken from the seer atop his watchtower and carried back to Ethel Rethor. Azore greeted it as the elusive Sceptre of Light and called its recovery the removal of a grave threat to the world. Whatever the cult had meant to do with it, the sceptre was out of its hands.', 'quest 5741 reward text'),
(40525, 2, 0, 255, 'The protector on Ranazjar Isle was called out and the long lost Book of the Ancients brought to Azore, who thanked its finder as a hero should be thanked. The book, with all the secrets of the naga written in it, is to be passed on to the high council.', 'quest 6027 reward text (long lost; passed on to the high council; thanked as a hero)'),
(40527, 1, 0, 255, 'The Pariah''s instructions name his prize. The Nameless Prophet, highest of all the tribes in spiritual matters, wears the Amulet of Spirits without knowing its true power, and five gems missing from it are held by the spirits of the first khans, Gelk, Kolk, Magra, Maraudos and Veng, who roam Maraudon. Slaying the Prophet is heresy, and the rest would condemn any centaur for even thinking it. Made whole as the Amulet of Union, it would let him reform the tribes.', 'quest 7067 description (he passes a parchment of instructions); page_text 2591 to 2596 (the Pariah''s instructions: Nameless Prophet, Amulet of Spirits, five gems, five khans, Amulet of Union, heresy)'),
(40527, 2, 0, 255, 'The Amulet of Union was brought to him at last, and the Pariah rejoiced: now the great task of uniting the tribes could begin. He gave thanks and a reward, and as they parted he told the one who had helped him that he hoped their next meeting would be on much different terms.', 'quest 7067 reward text'),
(40528, 1, 0, 255, 'Khan Dez''hepah was slain and his head laid before Felgur, a swift show of strength, and strength is what centaur understand best. The death of their leader would disrupt the Kolkar and give the other clans pause.', 'quest 1365 reward text; quest 1366 description (offered next by Felgur)'),
(40528, 2, 0, 255, 'Then the bleeding began: Felgur wanted ears from any clan at all, a hoard of them, to weaken their numbers and stamp out any thought of expansion. When the hoard was in, he was satisfied. By now, he said, the centaur must know the name of the one who hunted them, and respect it, and fear it, and know too the banner under which that hunter rides: the banner of the Horde.', 'quest 1366 reward text'),
(40529, 1, 0, 255, 'For the Gelkis the proofs ran long: the Magram meat stores raided until Uthek could hear their bellies grumble, a shard of draenethyst taken from the lost one Ongeku in the Swamp of Sorrows, and at last the head of the Magram Khan, Jehn. He was strong but stupid, Uthek said, blind to the greater strength of earth magic, and without him the Magram would fall.', 'quests 1370, 1373 descriptions and reward texts; quest 1374 description and reward text'),
(40529, 2, 0, 255, 'For the Magram the proofs were cruder: the tears of Theradras in the Gelkis cave smashed, to show that their mother would not save them, a new wooden target dummy for Warug''s amusement, and the head of the Gelkis Khan, Shaka. Warug set it on a pike and kept it by him, so that Shaka could see the strength of the Magram.', 'quests 1369, 1371 descriptions and reward texts; quest 1375 description and reward text'),
(40529, 3, 0, 255, 'Both roads ended in the Valley of Spears. With a mouthpiece taken from a trusted Maraudine, the war horn atop a high bluff was blown, and the Maraudine came in answer until Khan Hratha himself appeared and was slain, carrying a fragment of a key. His fall was hailed as the doom of the Maraudine, and each clan swore that it would now rule Desolace and remember the ally who had helped it.', 'quests 1380, 1381 descriptions and reward texts (war horn, mouthpiece, Khan Hratha, key fragment, each clan will rule and remember)'),
(40530, 1, 0, 255, 'The Malem wagon was found wrecked by spells and weapons, in a fight that had been swift and one-sided, with no blood and no bodies. A pendant lay in the wreckage, and footprints led south toward a fort where smoke rose from a kept fire. Vahlarriel was furious, for the two had been warned. From what the locals said, the fortress was infested with the Burning Blade, orcs dedicated to demon causes, who slay spies on sight.', 'quest 1437 reward text (spells and weapons, one-sided, no blood, no bodies); quest 1465 description and reward text (pendant, footprints south, kept fire, Burning Blade fortress); quest 1438 description (offered next: Dalinda first, Tyranis to be gauged)'),
(40530, 2, 0, 255, 'Vahlarriel''s superiors in Darnassus cared most that Dalinda come home safe; Tyranis was to be gauged first. Dalinda was found a prisoner within the fortress, brought there with her brother by the Burning Blade and sure she would be sacrificed. Coming to Desolace had been a mistake, she said: Tyranis had begun to crave knowledge of all things arcane, against the wishes of their people, and had made the journey even after hearing of the demons.', 'quest 1438 reward text; quest 1439 description (offered next: will not leave until his fate is known)'),
(40530, 3, 0, 255, 'She would not leave until his fate was known, and it was the fate she had dreaded. Tyranis had sought the cult''s secrets and counted himself among their kind, and he died at her rescuers'' hands, as he surely would have at her own people''s. Dalinda called it necessary, and asked forgiveness if her thanks did not sound sincere.', 'quest 1439 completion and reward text'),
(40530, 4, 0, 255, 'Only then did Dalinda flee the fortress. Partway out she sent her escort back to finish off the cultists and went on alone, and she reached Nijel''s Point under her own power. Vahlarriel was glad of it, but grieved that both had not come back. The shame of her brother''s choices is Dalinda''s to carry home to Darnassus.', 'creature_text 5644 (escort lines: finish off those you can, I should be fine on my own); quest 1440 reward text (arrived under her own power; Tyranis'' embarrassment hers to endure)'),
(40531, 1, 0, 255, 'Maurin read the runes as an old tongue, only distantly like Eredun, and the skin as a contract of some kind, signed by a demon: Lord Azrethoc. To find him Maurin first needed the scalp of a Hatefury shadowstalker from the ruins of Sargeron, to break any wards the demon held against scrying.', 'quest 1480 reward text; quest 1481 description (offered next)'),
(40531, 2, 0, 255, 'With the scalp in hand and an oracle crystal from the Slitherblade naga to focus the spell, Maurin called Azrethoc by his true name, and the demon lord''s image appeared. The creature was far more dangerous than Maurin had expected. Rather than face it alone he sent word to Takata Steelblade, the swordsman beside him, whose honor demanded he be told, with a warning not to press him too hard.', 'quests 1481, 1482 descriptions and reward texts; creature_text 4498 (I call your true name, Azrethoc); quest 1484 description'),
(40531, 3, 0, 255, 'Takata agreed that a demon seeking influence over the Burning Blade must be stopped, and sent champions directly south. Lord Azrethoc and his orc warlock servant Jugkar Grim''rod were slain at Mannoroc Coven, and Takata dared to hope that the Horde might one day have a place it could safely call home again.', 'quest 1488 description and reward text'),
(40532, 1, 0, 255, 'The red crystal was broken, though a demon spirit rose to guard what it sealed, and the Demon Box was carried back to Shadowprey. There Taiga opened it, and inside lay the Hand of Iruxos, the cult''s key to its portals.', 'quest 5381 reward text; smart_scripts 176581 (Hand of Iruxos Crystal summons Demon Spirit 11876); quest 5581 description (offered next)'),
(40532, 2, 0, 255, 'The Hand was a gruesome sight, but Taiga turned the cult''s own tool against it: carried into Mannoroc Coven, it could banish the portals. Each portal sent forth a guardian when the Hand was set against it, but six were banished and the flood of demons was stemmed. The effort had helped greatly in the fight against the demon threat, Taiga declared, and all of Azeroth was safer because of it.', 'quest 5581 description and reward text; smart_scripts 177243 (Demon Portal summons Demon Portal Guardian 11937)'),
(40533, 1, 0, 255, 'The chest was found curiously free of water damage, its top forced open and its magical traps long since fired, as the burn marks showed. Long, deep gouges along its sides had been made by no sword or dagger, and by neither man nor giant. It was empty.', 'quest 1454 reward text; quest 1455 description'),
(40533, 2, 0, 255, 'Kreldig blamed the Slitherblade naga, who make their home in sunken night elf ruins near Ranazjar Isle, and Karnitol''s satchel turned up among their tidehunters and sea witches. Those blasted naga, Kreldig grumbled: he would rather spend his life at war with the Horde than go up against their kind.', 'quest 1456 description and reward text'),
(40533, 3, 0, 255, 'Leftwitch''s list grew stranger as it went: scorpashi venom, the hide of aged kodo and no other, and at last felhound brains, nether wings and doomwarder blood from the demons of Mannoroc Coven. Kreldig had not even known there were demons in Desolace, a land he thought the centaur owned once the night elves left, and he wondered how they came to be there.', 'quest 1459 description; quest 1466 description and completion text'),
(40534, 1, 0, 255, 'Past the Kolkar village the caravan came through intact, and Smeed paid as promised, though he doubted it was prosperous to be paying the likes of a hired guard. If he were a bit taller, he mused, he would ride kodo-back with the biggest gun he could carry and show the centaur a thing or two himself.', 'quest 5821 completion and reward text'),
(40534, 2, 0, 255, 'The caravan came safely through Mannoroc Coven, and Smeed wiped his brow and thanked the goddess of greed, for if it ever disappeared he would be ruined. He still doubts the sense of paying so much to guard it, since Cork and Rigger make only one gold piece a week, but as long as they keep buying his kodo he cares little how they run their business.', 'quest 5943 completion and reward text'),
(40535, 1, 0, 255, 'The sorrow is the centaur''s own beginning. Ages ago Zaetar, first son of Cenarius, came together with Princess Theradras, an elemental force of earth somehow kin to the Old Gods, and their offspring became the centaur. The children repaid their father by killing him, and his remains lie in Maraudon still. The Circle seeks those strong enough to slay Theradras, so that Zaetar''s remains can be recovered and carried back to Stonetalon.', 'quests 7064, 7065 descriptions (Zaetar, Theradras, the centaur killed their father; slay Theradras, recover the remains, return to Stonetalon)'),
(40535, 2, 0, 255, 'Purified water from the orange crystal pool was poured on the Vylestem vines, and the corrupted scions Vyletongue sent up out of them were cut down. Some of the corruption he spread through Maraudon was healed and the plants could grow again, though much remains to be done.', 'quests 7029, 7041 descriptions, objectives and reward texts'),
(40535, 3, 0, 255, 'Both pieces of the Scepter of Celebras, the Celebrian Rod and the Celebrian Diamond, were taken back from Vyletongue and Noxxion, and Celebras woke as if from a nightmare that seemed it would never end. With the two parts of his scepter recovered, he has hope that Maraudon may one day be rid of the corruption.', 'quest 7044 description, objectives, completion and reward text (Celebras the Redeemed 13716 ends it)'),
(40535, 4, 0, 255, 'Princess Theradras was slain in the depths of Maraudon. Zaetar, brother to Remulos, had brought many pains to the world, Selendra said, and in the end they caused his death. It was the hardest of the tasks the dryads had come for, and Selendra rewarded her slayers with tokens of her people, as she had been given leave to do. Zaetar''s remains are not yet settled: on that, Selendra means to seek the wisdom of Keeper Marandis.', 'quest 7064 reward text (Horde, Selendra); quest 7064 completion text (Zaetar, brother to Remulos, brought many pains)'),
(40535, 5, 0, 255, 'Princess Theradras was slain in the depths of Maraudon. Zaetar, brother to Remulos, had brought many pains to the world and his own death with them, and there is a lesson in that, Marandis said. His remains did not come back with her slayers, and though it concerns him, Keeper Marandis will not question the will of Cenarius'' first born. Perhaps now, he hopes, the will of the centaur will break and their thirst for blood will lessen.', 'quest 7065 reward text (Alliance, Marandis); quest 7065 completion text (brother to Remulos; a lesson to all)');
